import unittest
from typing import List
from candidate import all_prefixes


class TestAllPrefixes(unittest.TestCase):
    def test_all_prefixes_normal_case(self):
        self.assertEqual(all_prefixes('abc'), ['a', 'ab', 'abc'])

    def test_all_prefixes_single_character(self):
        self.assertEqual(all_prefixes('a'), ['a'])

    def test_all_prefixes_two_characters(self):
        self.assertEqual(all_prefixes('ab'), ['a', 'ab'])

    def test_all_prefixes_empty_string(self):
        self.assertEqual(all_prefixes(''), [])

    def test_all_prefixes_five_characters(self):
        self.assertEqual(all_prefixes('hello'), ['h', 'he', 'hel', 'hell', 'hello'])

    def test_all_prefixes_with_spaces(self):
        self.assertEqual(all_prefixes('a b'), ['a', 'a ', 'a b'])

    def test_all_prefixes_with_leading_space(self):
        self.assertEqual(all_prefixes(' ab'), [' ', ' a', ' ab'])

    def test_all_prefixes_with_trailing_space(self):
        self.assertEqual(all_prefixes('ab '), ['a', 'ab', 'ab '])

    def test_all_prefixes_with_digits(self):
        self.assertEqual(all_prefixes('123'), ['1', '12', '123'])

    def test_all_prefixes_with_special_characters(self):
        self.assertEqual(all_prefixes('!@#'), ['!', '!@', '!@#'])

    def test_all_prefixes_with_unicode(self):
        self.assertEqual(all_prefixes('héllo'), ['h', 'hé', 'hél', 'héllo'])

    def test_all_prefixes_returns_list(self):
        self.assertIsInstance(all_prefixes('abc'), list)

    def test_all_prefixes_elements_are_strings(self):
        result = all_prefixes('abc')
        for item in result:
            self.assertIsInstance(item, str)

    def test_all_prefixes_result_length_matches_input_length(self):
        self.assertEqual(len(all_prefixes('abc')), 3)
        self.assertEqual(len(all_prefixes('hello world')), 11)

    def test_all_prefixes_order_shortest_to_longest(self):
        result = all_prefixes('abcdef')
        for i in range(len(result)):
            self.assertEqual(len(result[i]), i + 1)

    def test_all_prefixes_last_element_is_full_string(self):
        self.assertEqual(all_prefixes('test')[-1], 'test')

    def test_all_prefixes_first_element_is_first_char(self):
        self.assertEqual(all_prefixes('test')[0], 't')

    def test_all_prefixes_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            all_prefixes(None)

    def test_all_prefixes_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            all_prefixes(123)

    def test_all_prefixes_list_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            all_prefixes(['a', 'b'])

    def test_all_prefixes_empty_list_return_type(self):
        self.assertIsInstance(all_prefixes(''), list)
        self.assertEqual(all_prefixes(''), [])

    def test_all_prefixes_repeated_characters(self):
        self.assertEqual(all_prefixes('aaa'), ['a', 'aa', 'aaa'])

    def test_all_prefixes_newline_characters(self):
        self.assertEqual(all_prefixes('a\nb'), ['a', 'a\n', 'a\nb'])

    def test_all_prefixes_tab_characters(self):
        self.assertEqual(all_prefixes('a\tb'), ['a', 'a\t', 'a\tb'])

    def test_all_prefixes_mixed_content(self):
        self.assertEqual(all_prefixes('a1!'), ['a', 'a1', 'a1!'])

    def test_all_prefixes_long_string(self):
        s = 'abcdefghij'
        expected = [s[:i+1] for i in range(len(s))]
        self.assertEqual(all_prefixes(s), expected)

    def test_all_prefixes_does_not_modify_original_string(self):
        original = 'abc'
        _ = all_prefixes(original)
        self.assertEqual(original, 'abc')


if __name__ == '__main__':
    unittest.main()
